{
  "items": [
    {
      "name": "Finset.sup'_le",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SemilatticeSup α] {s : Finset β} (H : s.Nonempty) (f : β → α) {a : α},\n  (∀ b ∈ s, f b ≤ a) → s.sup' H f ≤ a"
    },
    {
      "name": "sSup_le",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteSemilatticeSup α] {s : Set α} {a : α}, (∀ b ∈ s, b ≤ a) → sSup s ≤ a"
    },
    {
      "name": "SupSet.sSup",
      "module_name": "Mathlib.Order.SetNotation",
      "kind": "definition",
      "type": "{α : Type u_1} → [self : SupSet α] → Set α → α"
    },
    {
      "name": "Finite.le_ciSup",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [Finite ι] [inst : ConditionallyCompleteLattice α] (f : ι → α) (i : ι), f i ≤ ⨆ j, f j"
    },
    {
      "name": "Real.sSup_le",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ} {a : ℝ}, (∀ x ∈ s, x ≤ a) → 0 ≤ a → sSup s ≤ a"
    },
    {
      "name": "sSup_le_iff",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteSemilatticeSup α] {s : Set α} {a : α}, sSup s ≤ a ↔ ∀ b ∈ s, b ≤ a"
    },
    {
      "name": "Finset.Nonempty.csSup_eq_max'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Finset",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : ConditionallyCompleteLinearOrder α] {s : Finset α} (h : s.Nonempty), sSup ↑s = s.max' h"
    },
    {
      "name": "Set.Finite.ciSup_lt_iff",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : ConditionallyCompleteLinearOrder α] {a : α} {s : Set ι} {f : ι → α},\n  s.Finite → (∃ x ∈ s, sSup ∅ ≤ f x) → (⨆ i ∈ s, f i < a ↔ ∀ x ∈ s, f x < a)"
    }
  ]
}
